float noise(vec2 p) {
    return sin(p.x) * cos(p.y);}




float fractalNoise(vec2 p) {   // фун-я фракталfractalNoise
    float n = 0.0;
    float amplitude = 1.0;
    float frequency = 1.0;
    for (int i = 0; i < 5; i++) {
        n += noise(p * frequency) * amplitude;
        frequency *= 2.0;
        amplitude *= 0.5; }




    return n;}
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;
    float time = iTime * 0.5;
    float n = fractalNoise(uv * 5.0 + vec2(time, time * 0.5));   // вогонь
    vec3 color = mix(vec3(1.0, 0.5, 0.1), vec3(0.9, 0.1, 0.05), n); // кольори вогню
    color *= 1.0 - smoothstep(0.2, 0.9, uv.y); // затухання вогню
    fragColor = vec4(color, 1.0);}
